dtsPropsFor.Button:
/** Visual style. default = solid brand purple (primary action); outline = bordered neutral; secondary = soft gray; ghost = no chrome until hover; destructive = soft red tint; link = purple text link. */
variant?: "default" | "outline" | "secondary" | "ghost" | "destructive" | "link";
/** Height scale: xs 24px, sm 28px, default 32px, lg 36px; icon* sizes are square icon-only buttons. */
size?: "default" | "xs" | "sm" | "lg" | "icon" | "icon-xs" | "icon-sm" | "icon-lg";
/** Render the single child (e.g. an <a>) with button styling instead of a <button>. */
asChild?: boolean;
disabled?: boolean;
type?: "button" | "submit" | "reset";
onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
className?: string;
/** Label text, optionally with a lucide icon (auto-sized to 16px). Mark a leading/trailing icon with data-icon="inline-start" / "inline-end" for tighter padding. */
children?: React.ReactNode;

dtsPropsFor.Badge:
/** default = solid purple; secondary = soft gray; destructive = soft red; outline = bordered; ghost/link = chrome-less. */
variant?: "default" | "secondary" | "destructive" | "outline" | "ghost" | "link";
/** Render the single child (e.g. an <a>) with badge styling. */
asChild?: boolean;
className?: string;
children?: React.ReactNode;

dtsPropsFor.Card:
/** Surface container (white, rounded-2xl, soft shadow). Compose with CardHeader > CardTitle + CardDescription (+ CardAction for a top-right control), CardContent, CardFooter - all exported from window.VaradhiUI. */
size?: "default" | "sm";
/** "custom" drops the built-in flex/padding/gap so you can lay out the inside yourself. */
layout?: "default" | "custom";
asChild?: boolean;
className?: string;
children?: React.ReactNode;

dtsPropsFor.Avatar:
/** Round avatar. Children: AvatarImage (src, alt) + AvatarFallback (initials, shown while the image loads or when it fails); optional AvatarBadge (status dot). Stack several inside AvatarGroup, with AvatarGroupCount for "+N". */
size?: "default" | "sm" | "lg";
className?: string;
children?: React.ReactNode;

dtsPropsFor.Input:
type?: string;
placeholder?: string;
value?: string;
defaultValue?: string;
onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
disabled?: boolean;
/** Shows the destructive border + ring. */
"aria-invalid"?: boolean;
id?: string;
name?: string;
className?: string;

dtsPropsFor.Label:
/** Associates with a control by id. */
htmlFor?: string;
className?: string;
children?: React.ReactNode;

dtsPropsFor.Progress:
/** 0-100. Renders a 4px track (bg-muted) with a purple fill; resize with className (e.g. "h-2"). */
value?: number;
className?: string;

dtsPropsFor.Separator:
orientation?: "horizontal" | "vertical";
/** true (default) = purely visual, hidden from assistive tech. */
decorative?: boolean;
className?: string;

dtsPropsFor.Switch:
checked?: boolean;
defaultChecked?: boolean;
onCheckedChange?: (checked: boolean) => void;
disabled?: boolean;
id?: string;
className?: string;

dtsPropsFor.Tabs:
/** Root (Radix Tabs). Compose: Tabs > TabsList (variant "default" pill track | "line" underline) > TabsTrigger value="..." ; then one TabsContent value="..." per tab. */
defaultValue?: string;
value?: string;
onValueChange?: (value: string) => void;
orientation?: "horizontal" | "vertical";
className?: string;
children?: React.ReactNode;

dtsPropsFor.Table:
/** Wraps the <table> in an overflow-x-auto container; pass false when a parent already scrolls. Compose: Table > TableHeader > TableRow > TableHead; TableBody > TableRow > TableCell; optional TableFooter, TableCaption. */
scrollable?: boolean;
className?: string;
children?: React.ReactNode;

dtsPropsFor.Select:
/** Root (Radix Select). Compose: Select > SelectTrigger (size "default" | "sm") > SelectValue placeholder="..."; SelectContent > SelectItem value="..." (optionally SelectGroup + SelectLabel, SelectSeparator). */
value?: string;
defaultValue?: string;
onValueChange?: (value: string) => void;
open?: boolean;
defaultOpen?: boolean;
disabled?: boolean;
name?: string;
children?: React.ReactNode;

dtsPropsFor.DropdownMenu:
/** Root (Radix DropdownMenu). Compose: DropdownMenu > DropdownMenuTrigger asChild > <Button/>; DropdownMenuContent (align "start" | "center" | "end") > DropdownMenuLabel, DropdownMenuItem (variant "default" | "destructive"; icon + text + optional DropdownMenuShortcut), DropdownMenuSeparator, DropdownMenuCheckboxItem, DropdownMenuRadioGroup > DropdownMenuRadioItem, DropdownMenuSub > DropdownMenuSubTrigger + DropdownMenuSubContent. */
open?: boolean;
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
/** Set false to keep the page interactive while open. */
modal?: boolean;
children?: React.ReactNode;

dtsPropsFor.Dialog:
/** Root (Radix Dialog). Compose: Dialog > DialogTrigger asChild > <Button/>; DialogContent (showCloseButton, default true) > DialogHeader > DialogTitle + DialogDescription; body; DialogFooter (showCloseButton adds an outline "Close") with Buttons. Use DialogClose asChild to make any button close it. */
open?: boolean;
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
modal?: boolean;
children?: React.ReactNode;

dtsPropsFor.AlertDialog:
/** Root (Radix AlertDialog) for confirmations. Compose: AlertDialog > AlertDialogTrigger asChild > <Button/>; AlertDialogContent (size "default" | "sm") > AlertDialogHeader > (AlertDialogMedia icon) AlertDialogTitle + AlertDialogDescription; AlertDialogFooter > AlertDialogCancel + AlertDialogAction (both take Button variant/size, e.g. variant="destructive"). */
open?: boolean;
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
children?: React.ReactNode;
